// Reads the shipped English UI catalog (src/i18n/locales/en/<namespace>.json), generated by
// `npm run i18n:extract`. The translation service only ever sends strings from this catalog, so
// no project, prompt, file name or other user content can reach a translation provider.
import { createHash } from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { PLURAL_CATEGORIES } from '../src/i18n/message-format.js';
import { NAMESPACES, isValidKey, namespaceOf } from '../src/i18n/namespaces.js';

const repositoryRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const DEFAULT_CATALOG_DIRECTORY = path.join(repositoryRoot, 'src', 'i18n', 'locales', 'en');
const MAX_CATALOG_BYTES = 2 * 1024 * 1024;
const MAX_STRING_LENGTH = 2000;

/** Stable hash of an English source value (string or plural forms), 16 hex digits. */
export function sourceHash(value) {
  const normalized =
    typeof value === 'string'
      ? value
      : Object.fromEntries(
          Object.keys(value)
            .sort()
            .map((key) => [key, value[key]]),
        );
  return createHash('sha256').update(JSON.stringify(normalized)).digest('hex').slice(0, 16);
}

function isValidValue(value) {
  if (typeof value === 'string') {
    return value.length > 0 && value.length <= MAX_STRING_LENGTH;
  }
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const forms = Object.entries(value);
  return (
    Object.hasOwn(value, 'other') &&
    forms.every(
      ([category, text]) =>
        PLURAL_CATEGORIES.includes(category) &&
        typeof text === 'string' &&
        text.length > 0 &&
        text.length <= MAX_STRING_LENGTH,
    )
  );
}

/**
 * @param {{ directory?: string }} options Folder of English namespace JSON files.
 * Results are cached per file modification time.
 */
export function createEnglishCatalog({ directory = DEFAULT_CATALOG_DIRECTORY } = {}) {
  const cache = new Map();

  function namespaces() {
    let names;
    try {
      names = fs.readdirSync(directory);
    } catch {
      return [];
    }
    return names
      .filter((name) => name.endsWith('.json'))
      .map((name) => name.slice(0, -5))
      .filter((name) => NAMESPACES.includes(name))
      .sort();
  }

  /** Map of key -> { value, hash } for one namespace; empty when it has no catalog. */
  function read(namespace) {
    if (!NAMESPACES.includes(namespace)) {
      return new Map();
    }
    const file = path.join(directory, `${namespace}.json`);
    let info;
    try {
      info = fs.statSync(file);
    } catch {
      return new Map();
    }
    const cached = cache.get(namespace);
    if (cached && cached.mtimeMs === info.mtimeMs && cached.size === info.size) {
      return cached.entries;
    }
    if (info.size > MAX_CATALOG_BYTES) {
      throw Error(`The English catalog for ${namespace} is too large.`);
    }
    const raw = JSON.parse(fs.readFileSync(file, 'utf8'));
    const entries = new Map();
    for (const [key, value] of Object.entries(raw)) {
      // Only well-formed keys of this namespace are served; anything else is ignored.
      if (isValidKey(key) && namespaceOf(key) === namespace && isValidValue(value)) {
        entries.set(key, { value, hash: sourceHash(value) });
      }
    }
    cache.set(namespace, { mtimeMs: info.mtimeMs, size: info.size, entries });
    return entries;
  }

  return { namespaces, read };
}
